// HMAC-SHA256 verify using Web Crypto (no require, works in n8n vm2 sandbox).
const secret = $env.SHOPIFY_WEBHOOK_SECRET;
if (!secret) throw new Error('SHOPIFY_WEBHOOK_SECRET not set on n8n');

async function computeHmacBase64(rawBody) {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw', enc.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']
  );
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(rawBody));
  let bin = '';
  const bytes = new Uint8Array(sig);
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin);
}

const items = $input.all();
const out = [];
for (const item of items) {
  const headers = item.json.headers || {};
  const topic = (headers['x-shopify-topic'] || '').toLowerCase();
  const hmac = headers['x-shopify-hmac-sha256'];
  const rawBody = typeof item.json.body === 'string'
    ? item.json.body
    : JSON.stringify(item.json.body);
  const computed = await computeHmacBase64(rawBody);
  if (computed !== hmac) {
    out.push({ json: { ok: false, error: 'bad-hmac', topic } });
    continue;
  }
  let order; try { order = JSON.parse(rawBody); } catch { order = item.json.body; }
  out.push({ json: { ok: true, topic, order } });
}
return out;

// Phone normalize + active-order guard + extract fields.
function toWaId(raw) {
  if (!raw) return null;
  let d = String(raw).replace(/\D/g, '');
  if (!d) return null;
  if (d.length === 11 && d.startsWith('0')) d = d.slice(1);
  if (d.length === 10) d = '91' + d;
  if (d.length < 11 || d.length > 15) return null;
  return d;
}
function firstName(...candidates) {
  for (const c of candidates) {
    const t = (c ?? '').trim();
    if (t) return t.split(/\s+/)[0];
  }
  return 'there';
}
const out = [];
for (const item of $input.all()) {
  const order = item.json.order;
  const orderRef = order.name || ('#' + order.order_number) || String(order.id);
  const cancelled = !!order.cancelled_at;
  const fin = String(order.financial_status ?? '').toLowerCase();
  const active = !cancelled && fin !== 'voided' && fin !== 'refunded';
  const waId = toWaId(
    order.customer?.phone ?? order.phone ?? order.shipping_address?.phone ?? order.billing_address?.phone
  );
  const name = firstName(order.customer?.first_name, order.shipping_address?.first_name, order.billing_address?.first_name);
  const total = String(order.total_price ?? order.current_total_price ?? '');
  out.push({
    json: {
      orderRef, active, waId, name, total,
      sentBy: 'journey:order_confirmation:' + orderRef,
      skipReason: !active ? 'order_not_active' : (!waId ? 'no_phone' : null),
    },
  });
}
return out;

// Carry forward the original normalize payload alongside the dedup result.
const prev = $('Extract + Normalize').first().json;
const hit = $input.all().length > 0;
return [{ json: { ...prev, dedupHit: hit } }];

